python3 << 'EOF'
import hashlib

# Let me try harder - perhaps there's a specific format with type prefix
targets = {
    'e98d9238eb5b343ceb8661b78e939874148b90db64578db6e0412d48fa8d2a03': ('a', 'b'),
    'acb2a7efa7c69573268a09d6b8b0bde04864ec17fcd46b5d8f3d322e1307627b': ('c', 'd'),
}

def sha(s):
    if isinstance(s, str):
        s = s.encode()
    return hashlib.sha256(s).hexdigest()

# Maybe length prefixes (like protobuf/bincode)
import struct
for endian in ['<', '>']:
    for sz in [1, 2, 4, 8]:
        fmt = {1:'B', 2:'H', 4:'I', 8:'Q'}[sz]
        for q, a in targets.values():
            qb = q.encode()
            ab = a.encode()
            # Different layouts
            for prefix_bytes in [b'', b'basic', b'\x00', b'\x01']:
                for layout in [
                    prefix_bytes + struct.pack(endian+fmt, len(qb)) + qb + struct.pack(endian+fmt, len(ab)) + ab,
                    struct.pack(endian+fmt, len(qb)) + qb + struct.pack(endian+fmt, len(ab)) + ab,
                    qb + struct.pack(endian+fmt, len(ab)) + ab,
                ]:
                    h = sha(layout)
                    if h in targets:
                        print(f'MATCH endian={endian} sz={sz} prefix={prefix_bytes!r}: {layout!r}')
                        print(f'  -> {h}')
print('done')
