"""Implementation of the hashcards subcommands."""
import os
import re
import sys
import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

import parse
import db


def _directory(parsed) -> str:
    d = parsed.get("directory") if parsed else None
    if d is None:
        d = os.getcwd()
    if not os.path.isdir(d):
        raise RuntimeError("directory does not exist.")
    return os.path.abspath(d)


def _load_cards_and_db(directory: str):
    cards = parse.load_collection(directory)
    con = db.open_db(directory)
    db.validate_hashes(con)
    return cards, con


def _ensure_cards_in_db(con, cards) -> None:
    added_at = _now_iso()
    existing = set(db.all_card_hashes(con))
    for c in cards:
        if c.hash not in existing:
            db.insert_new_card(con, c.hash, added_at)
    con.commit()


def _now_iso() -> str:
    # Local-time ISO 8601 with millisecond precision, no timezone (matches observed format)
    n = datetime.now()
    return n.strftime("%Y-%m-%dT%H:%M:%S") + "." + f"{n.microsecond // 1000:03d}"


def _today_str() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def count_tex_macros(directory: str) -> int:
    """Count TeX macros in macros.tex. A macro line is a non-comment line that
    contains at least one space character after stripping ``%`` comments.
    ``\\%`` escapes the percent sign.
    """
    path = os.path.join(directory, "macros.tex")
    if not os.path.isfile(path):
        return 0
    count = 0
    with open(path, "r", encoding="utf-8") as f:
        for raw in f:
            line = _strip_tex_comment(raw.rstrip("\n"))
            if " " in line:
                count += 1
    return count


def _strip_tex_comment(line: str) -> str:
    out = []
    i = 0
    L = len(line)
    while i < L:
        c = line[i]
        if c == "\\" and i + 1 < L and line[i + 1] == "%":
            out.append("\\%")
            i += 2
            continue
        if c == "%":
            break
        out.append(c)
        i += 1
    return "".join(out)


def parse_tex_macros(directory: str):
    """Return list of (name, value) pairs from macros.tex."""
    path = os.path.join(directory, "macros.tex")
    result = []
    if not os.path.isfile(path):
        return result
    with open(path, "r", encoding="utf-8") as f:
        for raw in f:
            line = _strip_tex_comment(raw.rstrip("\n"))
            if " " not in line:
                continue
            # Split at first space
            name, value = line.split(" ", 1)
            result.append((name, value))
    return result


def run_check(parsed) -> int:
    directory = _directory(parsed)
    cards = parse.load_collection(directory)
    con = db.open_db(directory)
    db.validate_hashes(con)
    sys.stdout.write("ok\n")
    return 0


def run_stats(parsed) -> int:
    directory = _directory(parsed)
    fmt = parsed.get("format", "html")
    if fmt == "html":
        sys.stdout.write("HTML output is not implemented yet.\n")
        return 0
    cards, con = _load_cards_and_db(directory)
    cards_in_deck = len(cards)
    cards_in_db = len(db.all_card_hashes(con))
    tex_macro_count = count_tex_macros(directory)
    today = _today_str()
    reviewed_today = db.cards_reviewed_today(con, today)
    result = {
        "cardsInDeckCount": cards_in_deck,
        "cardsInDbCount": cards_in_db,
        "texMacroCount": tex_macro_count,
        "cardsReviewedTodayCount": reviewed_today,
    }
    sys.stdout.write(json.dumps(result, indent=2) + "\n")
    return 0


def _card_to_json(card, perf) -> dict:
    content = {}
    if isinstance(card.content, parse.Basic):
        content = {"basic": {
            "question": card.content.question,
            "answer": card.content.answer,
        }}
    elif isinstance(card.content, parse.Cloze):
        content = {"cloze": {
            "text": card.content.text,
            "start": card.content.start,
            "end": card.content.end,
        }}
    return {
        "hash": card.hash,
        "familyHash": card.family_hash,
        "deckName": card.deck_name,
        "location": {
            "filePath": card.file_path,
            "lineStart": card.line_start,
            "lineEnd": card.line_end,
        },
        "content": content,
        "performance": perf,
    }


def _card_perf(con, card_hash):
    row = db.fetch_card(con, card_hash)
    if row is None or row[2] is None:  # no last_reviewed_at means no perf
        return None
    (_, added_at, last_reviewed_at, stability, difficulty,
     interval_raw, interval_days, due_date, review_count) = row
    if stability is None:
        return None
    return {
        "addedAt": added_at,
        "lastReviewedAt": last_reviewed_at,
        "stability": stability,
        "difficulty": difficulty,
        "intervalRaw": interval_raw,
        "intervalDays": interval_days,
        "dueDate": due_date,
        "reviewCount": review_count,
    }


def run_export(parsed) -> int:
    directory = _directory(parsed)
    output = parsed.get("output")
    cards, con = _load_cards_and_db(directory)
    cards.sort(key=lambda c: c.hash)
    cards_json = [_card_to_json(c, _card_perf(con, c.hash)) for c in cards]
    sessions = []
    for row in con.execute(
        "SELECT session_id, started_at, ended_at FROM sessions ORDER BY session_id"
    ):
        sid, started_at, ended_at = row
        rv = [
            {
                "cardHash": r[0],
                "reviewedAt": r[1],
                "grade": r[2],
                "stability": r[3],
                "difficulty": r[4],
                "intervalRaw": r[5],
                "intervalDays": r[6],
                "dueDate": r[7],
            }
            for r in con.execute(
                "SELECT card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date FROM reviews WHERE session_id=? ORDER BY review_id",
                (sid,),
            )
        ]
        sessions.append({
            "sessionId": sid,
            "startedAt": started_at,
            "endedAt": ended_at,
            "reviews": rv,
        })
    result = {"cards": cards_json, "sessions": sessions}
    text = json.dumps(result, indent=2, ensure_ascii=False) + "\n"
    if output:
        with open(output, "w", encoding="utf-8") as f:
            f.write(text)
    else:
        sys.stdout.write(text)
    return 0


def run_orphans_list(parsed) -> int:
    directory = _directory(parsed)
    con = db.open_db(directory)
    db.validate_hashes(con)
    cards = parse.load_collection(directory)
    deck_hashes = {c.hash for c in cards}
    for h in sorted(db.all_card_hashes(con)):
        if h not in deck_hashes:
            sys.stdout.write(h + "\n")
    return 0


def run_orphans_delete(parsed) -> int:
    directory = _directory(parsed)
    con = db.open_db(directory)
    db.validate_hashes(con)
    cards = parse.load_collection(directory)
    deck_hashes = {c.hash for c in cards}
    orphans = [h for h in db.all_card_hashes(con) if h not in deck_hashes]
    orphans.sort()
    for h in orphans:
        sys.stdout.write(h + "\n")
    db.delete_cards(con, orphans)
    return 0


def run_drill(parsed) -> int:
    directory = _directory(parsed)
    from drill import serve_drill
    return serve_drill(directory, parsed)
PYEOF
