# Minimal stub assets for KaTeX endpoints. Real katex is too large to bundle
# by hand; we return a short stub that loads without errors.
KATEX_CSS_STUB = "/* katex css stub */\n"
KATEX_JS_STUB = "/* katex js stub */\nwindow.katex = undefined;\n"
MHCHEM_JS_STUB = "/* mhchem stub */\n"


class _DrillState:
    def __init__(self, directory: str, opts: dict):
        self.directory = directory
        self.opts = opts
        self.lock = threading.Lock()
        self.started_at = _now_iso()
        self.reviewed = 0
        self.history = []  # list of (card_hash, prev_state)
        self.queue = []  # list of cards
        self.revealed = False
        self.last_action = None
        self.finished = False
        self.finished_at: str = ""
        self.total = 0
        self.macros = parse_tex_macros(directory)
        self._load_cards()

    def _load_cards(self) -> None:
        cards = parse.load_collection(self.directory)
        if self.opts.get("from_deck"):
            cards = [c for c in cards if c.deck_name == self.opts["from_deck"]]
        self.con = db.open_db(self.directory)
        db.validate_hashes(self.con)
        # Ensure all cards are in DB
        added_at = _now_iso()
        existing = set(db.all_card_hashes(self.con))
        for c in cards:
            if c.hash not in existing:
                db.insert_new_card(self.con, c.hash, added_at)
        self.con.commit()
        # Determine due cards: new (never reviewed) or due_date <= today
        today = date.today().isoformat()
        due = []
        for c in cards:
            row = db.fetch_card(self.con, c.hash)
            if row is None:
                continue
            last_reviewed_at = row[2]
            due_date = row[7]
            if last_reviewed_at is None or (due_date is not None and due_date <= today):
                due.append((c, row))
        # New card limit
        ncl = self.opts.get("new_card_limit")
        if ncl is not None:
            kept = []
            new_seen = 0
            for c, row in due:
                if row[2] is None:  # new card
                    if new_seen < ncl:
                        kept.append((c, row))
                        new_seen += 1
                else:
                    kept.append((c, row))
            due = kept
        cl = self.opts.get("card_limit")
        if cl is not None:
            due = due[:cl]
        self.queue = [c for c, _ in due]
        self.total = len(self.queue)

    def current(self):
        return self.queue[0] if self.queue else None

    def rate(self, grade: str) -> None:
        card = self.current()
        if card is None:
            return
        row = db.fetch_card(self.con, card.hash)
        prev_s = row[3]
        prev_d = row[4]
        prev_count = row[8]
        state = fsrs.schedule_card(prev_s, prev_d, grade)
        reviewed_at = _now_iso()
        if state["stability"] is None:
            # Forgot on a new card -> keep card, push to back of queue
            self.queue.append(self.queue.pop(0))
            return
        due_date = (date.today() + timedelta(days=state["interval_days"])) .isoformat()
        session_id = db.insert_session(self.con, self.started_at, reviewed_at)
        db.insert_review(
            self.con, session_id, card.hash, reviewed_at, grade,
            state["stability"], state["difficulty"], state["interval_raw"],
            state["interval_days"], due_date,
        )
        db.update_card_state(
            self.con, card.hash, reviewed_at,
            state["stability"], state["difficulty"], state["interval_raw"],
            state["interval_days"], due_date, prev_count + 1,
        )
        self.con.commit()
        self.queue.pop(0)
        self.reviewed += 1

    def end(self) -> None:
        self.finished = True
        self.finished_at = _now_iso()


def serve_drill(directory: str, opts: dict) -> int:
    state = _DrillState(directory, opts)

    if not state.queue:
        sys.stdout.write("No cards due today.\n")
        return 0

    host = opts.get("host", "127.0.0.1")
    port = int(opts.get("port", 8000))

    handler = _make_handler(state)
    try:
        server = ThreadingHTTPServer((host, port), handler)
    except OSError as e:
        raise RuntimeError(f"I/O error: {e!r}")

    server.shutdown_requested = False

    if opts.get("open_browser", True):
        try:
            import webbrowser
            webbrowser.open(f"http://{host}:{port}/")
        except Exception:
            pass

    def _serve():
        while not server.shutdown_requested:
            server.handle_request()

    thread = threading.Thread(target=_serve, daemon=True)
    thread.start()

    # Block until told to shutdown.
    try:
        while not server.shutdown_requested:
            thread.join(0.5)
    except KeyboardInterrupt:
        pass
    return 0


def _make_handler(state: _DrillState):
    class Handler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def log_message(self, fmt, *args):  # quiet
            return

        def _send(self, code: int, body: bytes, content_type: str = "text/html; charset=utf-8"):
            self.send_response(code)
            self.send_header("content-type", content_type)
            self.send_header("content-length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _not_found(self):
            self._send(404, b"Not Found")

        def do_GET(self):
            path = self.path.split("?", 1)[0]
            if path == "/":
                body = _render_page(state).encode("utf-8")
                return self._send(200, body)
            if path == "/style.css":
                return self._send(200, STYLE_CSS.encode("utf-8"), "text/css; charset=utf-8")
            if path == "/script.js":
                return self._send(200, _render_script(state).encode("utf-8"), "application/javascript; charset=utf-8")
            if path == "/katex/katex.css":
                return self._send(200, KATEX_CSS_STUB.encode("utf-8"), "text/css; charset=utf-8")
            if path == "/katex/katex.js":
                return self._send(200, KATEX_JS_STUB.encode("utf-8"), "application/javascript; charset=utf-8")
            if path == "/katex/mhchem.js":
                return self._send(200, MHCHEM_JS_STUB.encode("utf-8"), "application/javascript; charset=utf-8")
            return self._not_found()

        def do_POST(self):
            if self.path.split("?", 1)[0] != "/":
                return self._not_found()
            length = int(self.headers.get("content-length", "0") or 0)
            body = self.rfile.read(length).decode("utf-8") if length else ""
            params = up.parse_qs(body)
            action = params.get("action", [""])[0]
            with state.lock:
                if action == "Reveal":
                    state.revealed = True
                elif action in ("Forgot", "Hard", "Good", "Easy"):
                    state.rate(action.lower())
                    state.revealed = False
                    if not state.queue and not state.finished:
                        state.end()
                elif action == "End":
                    state.end()
                elif action == "Shutdown":
                    self.server.shutdown_requested = True
                elif action == "Undo":
                    pass  # not implemented
            self.send_response(303)
            self.send_header("location", "/")
            self.send_header("content-length", "0")
            self.end_headers()

    return Handler


def _render_script(state: _DrillState) -> str:
    prelude = "let MACROS = {};\n"
    for name, value in state.macros:
        prelude += f"MACROS['{_js_escape(name)}'] = '{_js_escape(value)}';\n"
    return prelude + SCRIPT_JS_TAIL


def _js_escape(s: str) -> str:
    out = []
    for c in s:
        if c == "\\":
            out.append("\\\\")
        elif c == "'":
            out.append("\\'")
        elif c == "\n":
            out.append("\\n")
        else:
            out.append(c)
    return "".join(out)


def _render_page(state: _DrillState) -> str:
    if state.finished:
        return _render_finished(state)
    card = state.current()
    if card is None:
        state.end()
        return _render_finished(state)
    total = state.total
    done = state.reviewed
    pct = 0 if total == 0 else int(100 * done / total)
    deck_name = html.escape(card.deck_name)
    # Body of the card
    if isinstance(card.content, parse.Basic):
        q = _render_markdown_inline(card.content.question)
        if state.revealed:
            card_body = f"<div class='prompt rich-text'>{q}</div><hr><div class='answer rich-text'>{_render_markdown_inline(card.content.answer)}</div>"
        else:
            card_body = f"<div class='prompt rich-text'>{q}</div>"
    else:
        # Cloze
        c: parse.Cloze = card.content
        start, end = c.start, c.end
        if end == (1 << 64) - 1:
            # Empty cloze
            s = c.text[:start] + "<span class='cloze revealed' style='color:transparent;'></span>" + c.text[start:]
        else:
            before = html.escape(c.text[:start])
            inner = html.escape(c.text[start:end + 1])
            after = html.escape(c.text[end + 1:])
            if state.revealed:
                s = before + f"<span class='cloze revealed'>{inner}</span>" + after
            else:
                hidden = "." * len(inner)
                if len(hidden) < 3:
                    hidden = "..."
                s = before + f"<span class='cloze'>{hidden}</span>" + after
        # Normalise paragraphs similar to observed output
        paragraphs = [f"<p>{line}</p>" for line in s.split("\n\n")]
        card_body = "<div class='prompt rich-text'>" + "\n".join(paragraphs) + "\n</div>"
    # Controls
    can_undo = "disabled" if not state.history else ""
    undo = f'<input id="undo" type="submit" name="action" value="Undo" {can_undo}>'
    reveal_or_rate = ""
    if state.revealed:
        if state.opts.get("answer_controls", "full") == "binary":
            reveal_or_rate = (
                '<input type="submit" name="action" value="Forgot">'
                '<input type="submit" name="action" value="Good">'
            )
        else:
            reveal_or_rate = (
                '<input type="submit" name="action" value="Forgot">'
                '<input type="submit" name="action" value="Hard">'
                '<input type="submit" name="action" value="Good">'
                '<input type="submit" name="action" value="Easy">'
            )
    else:
        reveal_or_rate = '<input id="reveal" type="submit" name="action" value="Reveal" title="Show the answer. Shortcut: space.">'
    end_btn = '<input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)">'

    page = (
        PAGE_HEAD
        + f"<div class=\"root\"><div class=\"header\"><div class=\"progress-bar\"><div class=\"progress-fill\" style=\"width: {pct}%;\"></div></div></div>"
        + f"<div class=\"card-container\"><div class=\"card\"><div class=\"card-header\"><h1>{deck_name}</h1></div><div class=\"card-content\">{card_body}</div></div></div>"
        + f"<div class=\"controls\"><form action=\"/\" method=\"post\">{undo}<div class=\"spacer\"></div>{reveal_or_rate}<div class=\"spacer\"></div>{end_btn}</form></div></div>"
        + "<script src=\"/script.js\"></script></body></html>"
    )
    return page


def _render_markdown_inline(md: str) -> str:
    """Render a tiny subset of markdown: paragraphs, emphasis, code, links."""
    # Escape HTML
    parts = md.split("\n\n")
    out_parts = []
    for part in parts:
        s = html.escape(part)
        out_parts.append("<p>" + s.replace("\n", "\n") + "</p>")
    return "\n".join(out_parts) + "\n"


def _fmt_dt(iso_s: str) -> str:
    # strip fractional seconds and T separator
    t = iso_s[:19].replace("T", " ")
    return t


def _duration_seconds(started: str, ended: str) -> int:
    def parse(iso):
        return datetime.strptime(iso[:19], "%Y-%m-%dT%H:%M:%S")
    try:
        d = (parse(ended) - parse(started)).total_seconds()
    except Exception:
        return 0
    return max(0, int(d))


def _render_finished(state: _DrillState) -> str:
    started = state.started_at
    finished = state.finished_at or _now_iso()
    duration = _duration_seconds(started, finished)
    pace = (duration / state.reviewed) if state.reviewed else 0
    pace_str = f"{pace:.2f}"
    rows = (
        f"<tr><td class=\"key\">Total Cards</td><td class=\"val\">{state.total}</td></tr>"
        f"<tr><td class=\"key\">Cards Reviewed</td><td class=\"val\">{state.reviewed}</td></tr>"
        f"<tr><td class=\"key\">Started</td><td class=\"val\">{_fmt_dt(started)}</td></tr>"
        f"<tr><td class=\"key\">Finished</td><td class=\"val\">{_fmt_dt(finished)}</td></tr>"
        f"<tr><td class=\"key\">Duration (seconds)</td><td class=\"val\">{duration}</td></tr>"
        f"<tr><td class=\"key\">Pace (s/card)</td><td class=\"val\">{pace_str}</td></tr>"
    )
    body = (
        f"<div class=\"finished\"><h1>Session Completed 🎉</h1>"
        f"<div class=\"summary\">Reviewed {state.reviewed} cards in {duration} seconds.</div>"
        f"<h2>Session Stats</h2>"
        f"<div class=\"stats\"><table><tbody>{rows}</tbody></table></div>"
        f"<div class=\"shutdown-container\"><form action=\"/\" method=\"post\">"
        f"<input class=\"shutdown-button\" id=\"shutdown\" type=\"submit\" name=\"action\" value=\"Shutdown\" title=\"Shut down the server\"></form></div></div>"
    )
    return PAGE_HEAD + body + "<script src=\"/script.js\"></script></body></html>"
