"""Parse markdown files into cards."""
from dataclasses import dataclass
from typing import List, Optional, Tuple
import hashlib
import os


@dataclass
class Basic:
    question: str
    answer: str


@dataclass
class Cloze:
    text: str
    start: int
    end: int


@dataclass
class Card:
    hash: str
    family_hash: Optional[str]
    deck_name: str
    file_path: str
    line_start: int
    line_end: int
    content: object


class ParseError(Exception):
    def __init__(self, message: str, file: str, line: int):
        super().__init__(message)
        self.message = message
        self.file = file
        self.line = line

    def __str__(self):
        return f"Parse error: {self.message} Location: {self.file}:{self.line}"


def _canonical_basic(question: str, answer: str) -> str:
    h = hashlib.sha256()
    h.update(b"basic\x00")
    h.update(question.encode("utf-8"))
    h.update(b"\x00")
    h.update(answer.encode("utf-8"))
    return h.hexdigest()


def _canonical_cloze(text: str, start: int, end: int) -> str:
    h = hashlib.sha256()
    h.update(b"cloze\x00")
    h.update(text.encode("utf-8"))
    h.update(b"\x00")
    h.update(str(start).encode("ascii"))
    h.update(b"\x00")
    h.update(str(end).encode("ascii"))
    return h.hexdigest()


def _canonical_family(text: str) -> str:
    h = hashlib.sha256()
    h.update(b"family\x00")
    h.update(text.encode("utf-8"))
    return h.hexdigest()


def parse_file(file_path: str) -> List[Card]:
    with open(file_path, "rb") as f:
        raw = f.read().decode("utf-8")
    deck_name = os.path.splitext(os.path.basename(file_path))[0]
    return parse_text(raw, deck_name, file_path)


def parse_text(raw: str, deck_name: str, file_path: str) -> List[Card]:
    lines = raw.split("\n")
    # Strip exactly one trailing empty line (from the final \n)
    if lines and lines[-1] == "":
        lines = lines[:-1]

    cards: List[Card] = []
    i = 0
    n = len(lines)

    def is_marker(line: str) -> bool:
        return line.startswith("Q:") or line.startswith("A:") or line.startswith("C:")

    def eof_line_end(pos: int) -> int:
        """When the parsed card ends at EOF (pos == n), return n - 1."""
        return pos - 1

    while i < n:
        line = lines[i]
        if line.startswith("Q:"):
            q_start = i
            question_parts: List[str] = []
            rest = line[2:]
            if rest.startswith(" "):
                rest = rest[1:]
            if rest != "":
                question_parts.append(rest)
            i += 1
            hit_eof = False
            while i < n:
                l = lines[i]
                if l.startswith("A:"):
                    break
                if l.startswith("Q:") or l.startswith("C:"):
                    raise ParseError(
                        "File ended while reading a question without an answer.",
                        file_path,
                        i,
                    )
                question_parts.append(l)
                i += 1
            else:
                hit_eof = True
            if hit_eof:
                raise ParseError(
                    "File ended while reading a question without an answer.",
                    file_path,
                    i,
                )
            answer_parts: List[str] = []
            a_line = lines[i]
            rest = a_line[2:]
            if rest.startswith(" "):
                rest = rest[1:]
            if rest != "":
                answer_parts.append(rest)
            i += 1
            while i < n and not is_marker(lines[i]):
                answer_parts.append(lines[i])
                i += 1
            if i >= n:
                line_end = eof_line_end(n)
            else:
                line_end = i
            question_text = "\n".join(question_parts).rstrip("\n").strip()
            answer_text = "\n".join(answer_parts).rstrip("\n").strip()
            content = Basic(question_text, answer_text)
            h = _canonical_basic(question_text, answer_text)
            cards.append(Card(
                hash=h, family_hash=None, deck_name=deck_name,
                file_path=file_path, line_start=q_start, line_end=line_end,
                content=content,
            ))
            continue
        if line.startswith("A:"):
            raise ParseError(
                "Found answer tag without a question.",
                file_path, i,
            )
        if line.startswith("C:"):
            c_start = i
            parts: List[str] = []
            rest = line[2:]
            if rest.startswith(" "):
                rest = rest[1:]
            if rest != "":
                parts.append(rest)
            i += 1
            while i < n and not is_marker(lines[i]):
                parts.append(lines[i])
                i += 1
            if i >= n:
                c_end = eof_line_end(n)
            else:
                c_end = i
            while parts and parts[-1] == "":
                parts.pop()
            raw_text = "\n".join(parts)
            clean_text, clozes = _extract_clozes(raw_text)
            if not clozes:
                raise ParseError(
                    "Cloze card must contain at least one cloze deletion.",
                    file_path, i,
                )
            fam = _canonical_family(clean_text)
            for start, end in clozes:
